Следующая функция на JavaScript проверяет, является ли какое-либо из чисел в массиве простым числом, и если есть, то выводит это число на консоль:

```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      console.log(num);
      break; // выход из цикла, если найдено первое простое число
    }
  }
}

function isPrime(num) {
  if (num < 2) return false; // 0 и 1 не являются простыми числами
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) return false; // если число делится на любое число от 2 до sqrt(num), то оно не простое
  }
  return true; // если не найдено делителей, то число является простым
}

// Пример использования:
const arr = [12, 17, 19, 23, 29];
checkPrime(arr); // Выведет 17, 19, 23, 29 на консоль (12 не является простым числом)
```

В функции `checkPrime` мы проходимся по массиву и для каждого числа вызываем функцию `isPrime`, которая проверяет, является ли число простым. Если число является простым, то выводится на консоль и цикл прерывается с помощью `break`, так как нам не интересно проверять остальные числа в массиве. Если ни одно число в массиве не является простым, то ничего не будет выведено на консоль.

