```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // Слово, которое ищем
    int count = 0; // Счетчик вхождений слова

    cout << "Enter the word to search: ";
    cin >> word;

    string file_name;
    cout << "Enter the file name: ";
    cin >> file_name;

    // Открытие файла для чтения
    ifstream file(file_name);
    if (!file.is_open()) {
        cerr << "Error: Cannot open file." << endl;
        return 1;
    }

    // Пропуск заголовков
    string line;
    while (getline(file, line) && line.empty()) {}

    // Поиск слова в файле
    while (getline(file, line)) {
